const express = require('express');
const app = express();

// Mock database connection check function
// In a real implementation, this would use the pg library to connect to Postgres
function checkDatabaseConnection() {
  // For now, we'll simulate a successful connection
  // In production, this would attempt to connect to the actual Postgres instance
  // using DATABASE_URL from environment variables
  return Promise.resolve(true);
}

// Health endpoint for Kubernetes liveness probe
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Readiness probe endpoint - checks if service can reach Postgres
app.get('/healthz', async (req, res) => {
  try {
    const dbIsReady = await checkDatabaseConnection();
    if (dbIsReady) {
      res.status(200).json({ db: 'ok' });
    } else {
      res.status(503).json({ db: 'error', message: 'Database connection failed' });
    }
  } catch (error) {
    console.error('Health check failed:', error);
    res.status(503).json({ db: 'error', message: 'Database connection failed' });
  }
});

